type SectorDetailInput = Omit<ServiceDetailConfig, "serviceSlug" | "serviceTitle" | "categoryTitle">;

const sectorService = "environmental-technology-sector-specific";
const sectorServiceTitle = "Environmental, Technology & Sector Specific";
const sectorCategory = "professional-and-sector-specific-advisory";
const sectorCategoryTitle = "Professional & Sector-Specific Advisory";
const technologyCategory = "technology-privacy-and-digital";
const technologyCategoryTitle = "Technology, Privacy & Digital";
const esgCategory = "esg-and-sustainability";
const esgCategoryTitle = "ESG & Sustainability";

function createSectorDetail(input: SectorDetailInput): ServiceDetailConfig {
  return {
    ...input,
    serviceSlug: sectorService,
    serviceTitle: sectorServiceTitle,
    categoryTitle: input.categorySlug === esgCategory
      ? esgCategoryTitle
      : input.categorySlug === technologyCategory
        ? technologyCategoryTitle
        : sectorCategoryTitle,
  };
}

